{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Multiple lines of evidence point to at least one film surpassing $1B worldwide before May 1, 2026, including a 2025 precedent of several $1B titles.",
    "A strong 2026 slate of tentpole releases and expected global box office growth increase the odds.",
    "However, risks from China market performance and streaming shifts temper upside and justify a high-but-not-certainty assessment."
  ],
  "confidence": "high",
  "narrative": "Starting from a baseline anchor of 0.35 for the reference class, upward updates from a franchise-heavy 2026 slate, 2025 1B precedents, and forecasted growth push the probability toward a high posterior. Calibration accounts for correlated factors and residual risks, yielding an estimate near 0.98 with a tight uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "reference class is the historical incidence of at least one worldwide box-office 1B film in a given period; anchor probability reflects a plausible baseline before applying the current evidence."
    },
    "factor_updates": [
      {
        "factor": "Franchise-heavy release slate in 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Calendar dominated by tentpoles (Avengers, Spider-Man, Dune, Star Wars, etc.) increases number of potential 1B worldwide earners, justifying a significant upward adjustment."
      },
      {
        "factor": "Recent 1B worldwide crossovers in 2025 set precedent",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Multiple 1B titles in 2025 demonstrate sustained international demand and elevate the probability of 1B outcomes in 2026."
      },
      {
        "factor": "Projected 2026 global box office growth",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Forecasted growth to around $35B supports stronger grosses, contributing to probability of at least one 1B title."
      },
      {
        "factor": "Significant international market contributions, particularly from non-US films",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Non-US markets driving more than half of 1B totals, so international demand supports hitting the milestone."
      },
      {
        "factor": "Animated and family tentpoles crossing 1B+ in 2025",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Animated/family IP continuing to reach 1B increases the pool of potential 1B titles in 2026."
      },
      {
        "factor": "China market performance risk",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "China's slower growth or declines could reduce upside; this dampens probability somewhat."
      },
      {
        "factor": "Streaming shifts reducing theater share",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Increased streaming reduces theatrical share, tempering 1B upside despite strong slate."
      }
    ],
    "synthesis_rationale": "Starting from anchor 0.35, apply each 'up' factor to raise probability and 'down' factors to dampen. Cumulative effect, with inter-factor correlation (e.g., 2025 crossovers tied to 2026 slate and global growth), yields a high posterior near 0.98. Calibration notes reduce overconfidence given overlapping evidence; final interval reflects residual uncertainty."
  }
}

